export const OPS=['add','sub','mul','div'];
export const NAMES={add:'Addition',sub:'Subtraction',mul:'Multiplication',div:'Division',all:'All operations'};
export const STAGES=['Learning','Strengthening','Provisional','Confirmed'];
export const SAMPLE_TODAY='2026-11-03';
export const pct=(n,d)=>d?Math.round(100*n/d):null;
export const median=a=>{if(!a.length)return null;const b=[...a].sort((x,y)=>x-y),m=Math.floor(b.length/2);return b.length%2?b[m]:(b[m-1]+b[m])/2;};
export const shift=(date,n)=>new Date(Date.parse(date+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
export function canonical(op,a,b){return ['add','mul'].includes(op)?`${op}:${Math.min(a,b)}:${Math.max(a,b)}`:`${op}:${a}:${b}`;}
export function factBank(){const out=[];const add=(op,a,b,answer,symbol)=>out.push({id:canonical(op,a,b),op,a,b,answer,text:`${a} ${symbol} ${b}`});for(let a=0;a<=20;a++)for(let b=a;a+b<=20;b++)add('add',a,b,a+b,'+');for(let a=0;a<=20;a++)for(let b=0;b<=a;b++)add('sub',a,b,a-b,'−');for(let a=0;a<=12;a++)for(let b=a;b<=12;b++)add('mul',a,b,a*b,'×');for(let b=1;b<=12;b++)for(let q=0;q<=12;q++)add('div',b*q,b,q,'÷');return out;}
export function status(f){return f.refresh>0?'Learning':f.stage===4?'Confirmed':f.stage===3?'Provisional':f.stage>0?'Strengthening':'Learning';}
export function selectStudents(data,filters={}){return data.students.filter(s=>(!filters.school||filters.school==='all'||s.schoolId===filters.school)&&(!filters.classId||filters.classId==='all'||s.classId===filters.classId)&&(!filters.grade||filters.grade==='all'||s.grade===Number(filters.grade))&&(!filters.search||s.name.toLowerCase().includes(filters.search.toLowerCase())));}
export function latestChecks(data,ids,op,from,to){const allowed=new Set(ids),result=new Map();for(const c of data.checks){if(!allowed.has(c.studentId)||c.pathway!==op||c.durationSeconds!==90||!c.valid||!c.official||c.date<from||c.date>to)continue;const previous=result.get(c.studentId);if(!previous||c.date>previous.date)result.set(c.studentId,c);}return [...result.values()];}
export function metrics(data,students,{op='mul',days=28,today=SAMPLE_TODAY}={}){const ids=new Set(students.map(s=>s.id)),from=shift(today,-days+1),definitions=new Map(data.facts.map(f=>[f.id,f]));const facts=data.factStates.filter(f=>ids.has(f.studentId)&&(op==='all'||definitions.get(f.factId)?.op===op));const counts=Object.fromEntries(STAGES.map(s=>[s,0]));for(const f of facts)counts[status(f)]++;
 const checks=latestChecks(data,[...ids],op==='all'?'mixed':op,from,today),active=new Set(data.sessions.filter(s=>ids.has(s.studentId)&&!s.demo&&s.date>=shift(today,-6)&&s.date<=today).map(s=>s.studentId));
 const complete=students.filter(s=>{const fs=facts.filter(f=>f.studentId===s.id);return fs.length>0&&fs.every(f=>status(f)==='Confirmed');}).length;
 return {students:students.length,counts,totalFacts:facts.length,confirmedRate:pct(counts.Confirmed,facts.length),complete,completeRate:pct(complete,students.length),active:active.size,activeRate:pct(active.size,students.length),checks:checks.length,checkCoverage:pct(checks.length,students.length),missing:students.length-checks.length,medianCorrect:median(checks.map(c=>c.correct)),medianAccuracy:median(checks.map(c=>100*c.correct/c.attempted)),wrong:checks.reduce((n,c)=>n+c.incorrect,0),timeout:checks.reduce((n,c)=>n+c.timeouts,0),due:facts.filter(f=>f.stage>0&&f.due&&f.due<=today).length,refresh:facts.filter(f=>f.refresh>0).length};}
export function priorities(data,students,op='mul'){const ids=new Set(students.map(s=>s.id));return data.facts.filter(f=>op==='all'||f.op===op).map(f=>({...f,students:data.factStates.filter(s=>s.factId===f.id&&ids.has(s.studentId)&&status(s)==='Learning').map(s=>s.studentId)})).filter(f=>f.students.length).sort((a,b)=>b.students.length-a.students.length||a.id.localeCompare(b.id)).slice(0,5);}
export function growth(data,students,op='mul',days=28){const ids=new Set(students.map(s=>s.id)),end=data.meta.asOf,start=shift(end,-days+1);const rows=data.snapshots.filter(s=>ids.has(s.studentId)&&s.pathway===op&&s.date>=start&&s.date<=end);const dates=[...new Set(rows.map(s=>s.date))].sort();if(dates.length<2)return {points:[],matched:0,change:null};const first=rows.filter(r=>r.date===dates[0]),last=rows.filter(r=>r.date===dates.at(-1)),matched=first.filter(r=>last.some(l=>l.studentId===r.studentId)).map(r=>r.studentId);return {matched:matched.length,points:dates.map(date=>{const list=rows.filter(r=>r.date===date&&matched.includes(r.studentId));return {date,rate:list.length===matched.length?pct(list.filter(r=>r.fullSetConfirmed).length,list.length):null,n:list.length};}),change:matched.length?pct(last.filter(r=>matched.includes(r.studentId)&&r.fullSetConfirmed).length,matched.length)-pct(first.filter(r=>matched.includes(r.studentId)&&r.fullSetConfirmed).length,matched.length):null};}
function validateRelations(data){const fail=m=>{throw new Error(m);};if(data.schemaVersion!=='1.0')fail('Unsupported reporting schema');for(const k of ['schools','classes','students','facts','factStates','checks','sessions','responses','snapshots'])if(!Array.isArray(data[k]))fail('Missing '+k);for(const k of ['schools','classes','students','facts','checks','sessions','responses']){const ids=data[k].map(x=>x.id);if(new Set(ids).size!==ids.length)fail('Duplicate '+k+' identifier');}const schools=new Set(data.schools.map(s=>s.id)),classes=new Map(data.classes.map(s=>[s.id,s])),students=new Set(data.students.map(s=>s.id)),facts=new Set(data.facts.map(s=>s.id)),keys=new Set();for(const s of data.students)if(!schools.has(s.schoolId)||classes.get(s.classId)?.schoolId!==s.schoolId)fail('Invalid roster relationship');for(const f of data.factStates){const key=f.studentId+'/'+f.factId;if(keys.has(key))fail('Duplicate student fact');keys.add(key);if(!students.has(f.studentId)||!facts.has(f.factId)||!Number.isInteger(f.stage)||f.stage<0||f.stage>4)fail('Invalid fact state');}for(const c of data.checks)if(!students.has(c.studentId)||c.attempted<1||c.correct+c.incorrect+c.timeouts!==c.attempted||c.durationSeconds!==90)fail('Invalid check');for(const s of [...data.sessions,...data.snapshots])if(!students.has(s.studentId))fail('Unknown student');for(const r of data.responses)if(!students.has(r.studentId)||!facts.has(r.factId)||!['correct','incorrect','timeout'].includes(r.outcome)||r.elapsedMs<0||r.elapsedMs>3000)fail('Invalid response');return data;}
export function csv(rows){const cell=value=>{let s=String(value??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};return rows.map(r=>r.map(cell).join(',')).join('\r\n');}
export function validate(data){
 if(!data||typeof data!=='object')throw new Error('Missing reporting dataset');
 validateRelations(data);
 const invalid=m=>{throw new Error('Invalid '+m);},day=s=>typeof s==='string'&&/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(s)&&!Number.isNaN(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;
 if(!data.meta||!['sample','live'].includes(data.meta.mode)||!day(data.meta.asOf)||data.meta.responseLimitMs!==3000||!data.meta.timezone)invalid('report metadata');
 const paths=[...OPS,'mixed'];const unique=(rows,key,label)=>{const keys=rows.map(key);if(new Set(keys).size!==keys.length)invalid('duplicate '+label);};
 for(const f of data.facts)if(!OPS.includes(f.op)||f.id!==canonical(f.op,f.a,f.b))invalid('canonical fact');
 for(const f of data.factStates)if(!Number.isInteger(f.refresh)||f.refresh<0||f.refresh>2||(f.due!==null&&!day(f.due))||(f.lastSuccess!==null&&!day(f.lastSuccess))||!f.rulesVersion)invalid('fact metadata');
 for(const c of data.checks)if(!paths.includes(c.pathway)||!day(c.date)||![c.correct,c.incorrect,c.timeouts,c.attempted].every(n=>Number.isInteger(n)&&n>=0)||typeof c.valid!=='boolean'||typeof c.official!=='boolean'||!c.rulesVersion)invalid('check metadata');
 unique(data.checks.filter(c=>c.valid&&c.official),c=>[c.studentId,c.pathway,c.date].join('/'),'official check day');
 for(const s of data.sessions)if(!day(s.date)||!Number.isFinite(s.practiceMs)||s.practiceMs<0||typeof s.demo!=='boolean')invalid('session metadata');
 for(const r of data.responses)if(!day(r.date)||!Number.isFinite(r.elapsedMs)||typeof r.demo!=='boolean'||typeof r.assisted!=='boolean')invalid('response metadata');
 for(const s of data.snapshots)if(!day(s.date)||!paths.includes(s.pathway)||typeof s.fullSetConfirmed!=='boolean'||!s.rulesVersion)invalid('snapshot metadata');
 unique(data.snapshots,s=>[s.studentId,s.pathway,s.date].join('/'),'snapshot');return data;
}
